class Inventory:
    """Stock, removal rules, reporting and the command loop in one type."""

    def __init__(self):
        self.quantities = {}
        self.history = []

    def add(self, sku, qty):
        self.quantities[sku] = self.quantities.get(sku, 0) + qty
        self.history.append(("add", sku, qty))

    def remove(self, sku, qty):
        if self.quantities.get(sku, 0) < qty:
            self.history.append(("rejected", sku, qty))
            return False
        self.quantities[sku] = self.quantities[sku] - qty
        self.history.append(("remove", sku, qty))
        return True

    def count(self, sku):
        return self.quantities.get(sku, 0)

    def low(self, threshold):
        result = []
        for sku in self.quantities:
            if self.quantities[sku] < threshold:
                result.append(sku)
        result.sort()
        return result

    def report(self):
        lines = []
        for sku in sorted(self.quantities):
            lines.append(sku + ": " + str(self.quantities[sku]))
        return "\n".join(lines)

    def history_size(self):
        return len(self.history)

    def run(self, operations):
        outputs = []
        for op in operations:
            if op[0] == "add":
                outputs.append(self.add(op[1], op[2]))
            elif op[0] == "remove":
                outputs.append(self.remove(op[1], op[2]))
            elif op[0] == "count":
                outputs.append(self.count(op[1]))
            elif op[0] == "low":
                outputs.append(self.low(op[1]))
        return outputs


def run_inventory(operations):
    return Inventory().run(operations)
